/**
 * Represents a glucose measurement record persisted in the system.
 */
export interface GlucoseRecord {
  id: string;
  patientId: string;
  measuredAt: string;
  glucoseValue: number;
  unit: 'mmol/L' | 'mg/dL';
  note?: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * Represents the data required to create a glucose measurement record.
 */
export interface GlucoseRecordCreateInput {
  patientId: string;
  measuredAt: string;
  glucoseValue: number;
  unit: 'mmol/L' | 'mg/dL';
  note?: string;
}

/**
 * Represents the data allowed when updating a glucose measurement record.
 */
export interface GlucoseRecordUpdateInput {
  measuredAt?: string;
  glucoseValue?: number;
  unit?: 'mmol/L' | 'mg/dL';
  note?: string;
}

import type { GlucoseRecord } from './types';

/**
 * Represents a history event associated with a glucose measurement record.
 */
export interface GlucoseRecordHistoryEvent {
  id: string;
  recordId: string;
  action: 'created' | 'updated' | 'deleted';
  occurredAt: string;
  snapshot?: GlucoseRecord;
}

import {
  GlucoseRecord,
  GlucoseRecordCreateInput,
  GlucoseRecordUpdateInput,
} from './types';

/**
 * In-memory repository for glucose records.
 */
export class GlucoseRecordRepository {
  private readonly records: Map<string, GlucoseRecord>;

  private idCounter: number;

  /**
   * Creates a new repository instance.
   */
  public constructor() {
    this.records = new Map<string, GlucoseRecord>();
    this.idCounter = 0;
  }

  /**
   * Lists all glucose records for a patient.
   *
   * @param patientId - The patient identifier.
   * @returns A promise resolving to the matching records.
   */
  public async list(patientId: string): Promise<GlucoseRecord[]> {
    if (patientId.length === 0) {
      return [];
    }

    const matches: GlucoseRecord[] = [];
    for (const record of this.records.values()) {
      if (record.patientId === patientId) {
        matches.push({ ...record });
      }
    }

    return matches;
  }

  /**
   * Gets a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to the matching record or null.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    const record: GlucoseRecord | undefined = this.records.get(id);
    return record === undefined ? null : { ...record };
  }

  /**
   * Creates a new glucose record.
   *
   * @param input - The record creation input.
   * @returns A promise resolving to the created record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    const now: string = new Date().toISOString();
    const id: string = this.generateId();
    const record: GlucoseRecord = {
      id,
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      note: input.note,
      createdAt: now,
      updatedAt: now,
    };

    this.records.set(id, record);
    return { ...record };
  }

  /**
   * Updates an existing glucose record.
   *
   * @param id - The record identifier.
   * @param input - The record update input.
   * @returns A promise resolving to the updated record or null.
   */
  public async update(
    id: string,
    input: GlucoseRecordUpdateInput,
  ): Promise<GlucoseRecord | null> {
    const existing: GlucoseRecord | undefined = this.records.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      measuredAt: input.measuredAt ?? existing.measuredAt,
      glucoseValue: input.glucoseValue ?? existing.glucoseValue,
      unit: input.unit ?? existing.unit,
      note: input.note !== undefined ? input.note : existing.note,
      updatedAt: new Date().toISOString(),
    };

    this.records.set(id, updated);
    return { ...updated };
  }

  /**
   * Deletes a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to true when deleted, otherwise false.
   */
  public async delete(id: string): Promise<boolean> {
    return this.records.delete(id);
  }

  private generateId(): string {
    this.idCounter += 1;
    return `record-${this.idCounter}`;
  }
}

import type { GlucoseRecord } from './types';
import type { GlucoseRecordHistoryEvent } from './history-types';

/**
 * In-memory history service for glucose record audit events.
 */
export class GlucoseRecordHistoryService {
  private readonly events: GlucoseRecordHistoryEvent[] = [];
  private readonly recordToPatientId: Map<string, string> = new Map<string, string>();

  /**
   * Appends a created event for the given record.
   *
   * @param record - The created glucose record.
   */
  public appendCreated(record: GlucoseRecord): void {
    this.validateRecord(record, 'record');
    this.recordToPatientId.set(record.id, record.patientId);
    this.events.push(this.createEvent('created', record.id, record));
  }

  /**
   * Appends an updated event for the given record transition.
   *
   * @param before - The record state before the update.
   * @param after - The record state after the update.
   */
  public appendUpdated(before: GlucoseRecord, after: GlucoseRecord): void {
    this.validateRecord(before, 'before');
    this.validateRecord(after, 'after');

    if (before.id !== after.id) {
      throw new Error('Updated record ids must match.');
    }

    this.recordToPatientId.set(after.id, after.patientId);
    this.events.push(this.createEvent('updated', after.id, after));
  }

  /**
   * Appends a deleted event for the given record.
   *
   * @param record - The deleted glucose record.
   */
  public appendDeleted(record: GlucoseRecord): void {
    this.validateRecord(record, 'record');
    this.recordToPatientId.set(record.id, record.patientId);
    this.events.push(this.createEvent('deleted', record.id, record));
  }

  /**
   * Lists history events for a specific record id in chronological order.
   *
   * @param recordId - The record identifier.
   * @returns A promise resolving to matching history events.
   */
  public async listByRecordId(recordId: string): Promise<GlucoseRecordHistoryEvent[]> {
    this.validateNonEmptyString(recordId, 'recordId');
    return this.listEvents((event: GlucoseRecordHistoryEvent) => event.recordId === recordId);
  }

  /**
   * Lists all history events for a patient across all of their records in chronological order.
   *
   * @param patientId - The patient identifier.
   * @returns A promise resolving to matching history events.
   */
  public async listAll(patientId: string): Promise<GlucoseRecordHistoryEvent[]> {
    this.validateNonEmptyString(patientId, 'patientId');

    return this.listEvents((event: GlucoseRecordHistoryEvent) => {
      const knownPatientId: string | undefined = this.recordToPatientId.get(event.recordId);
      if (knownPatientId === patientId) {
        return true;
      }

      return event.snapshot?.patientId === patientId;
    });
  }

  private createEvent(
    action: 'created' | 'updated' | 'deleted',
    recordId: string,
    snapshot?: GlucoseRecord,
  ): GlucoseRecordHistoryEvent {
    return {
      id: this.generateEventId(),
      recordId,
      action,
      occurredAt: new Date().toISOString(),
      snapshot: snapshot === undefined ? undefined : this.cloneRecord(snapshot),
    };
  }

  private listEvents(
    predicate: (event: GlucoseRecordHistoryEvent) => boolean,
  ): Promise<GlucoseRecordHistoryEvent[]> {
    const results: GlucoseRecordHistoryEvent[] = this.events
      .filter(predicate)
      .map((event: GlucoseRecordHistoryEvent) => this.cloneEvent(event))
      .sort((left: GlucoseRecordHistoryEvent, right: GlucoseRecordHistoryEvent) => {
        if (left.occurredAt < right.occurredAt) {
          return -1;
        }
        if (left.occurredAt > right.occurredAt) {
          return 1;
        }
        return left.id.localeCompare(right.id);
      });

    return Promise.resolve(results);
  }

  private cloneEvent(event: GlucoseRecordHistoryEvent): GlucoseRecordHistoryEvent {
    return {
      id: event.id,
      recordId: event.recordId,
      action: event.action,
      occurredAt: event.occurredAt,
      snapshot: event.snapshot === undefined ? undefined : this.cloneRecord(event.snapshot),
    };
  }

  private cloneRecord(record: GlucoseRecord): GlucoseRecord {
    return {
      id: record.id,
      patientId: record.patientId,
      measuredAt: record.measuredAt,
      glucoseValue: record.glucoseValue,
      unit: record.unit,
      note: record.note,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt,
    };
  }

  private generateEventId(): string {
    const timestamp: string = new Date().toISOString();
    const randomPart: string = Math.random().toString(36).slice(2, 10);
    return `history_${timestamp}_${randomPart}`;
  }

  private validateRecord(record: GlucoseRecord, parameterName: string): void {
    if (record === null || record === undefined) {
      throw new Error(`${parameterName} is required.`);
    }
    this.validateNonEmptyString(record.id, `${parameterName}.id`);
    this.validateNonEmptyString(record.patientId, `${parameterName}.patientId`);
    this.validateNonEmptyString(record.measuredAt, `${parameterName}.measuredAt`);
    this.validateNonEmptyString(record.unit, `${parameterName}.unit`);
    this.validateNonEmptyString(record.createdAt, `${parameterName}.createdAt`);
    this.validateNonEmptyString(record.updatedAt, `${parameterName}.updatedAt`);
    if (typeof record.glucoseValue !== 'number' || Number.isNaN(record.glucoseValue)) {
      throw new Error(`${parameterName}.glucoseValue must be a valid number.`);
    }
    if (record.note !== undefined && record.note === null) {
      throw new Error(`${parameterName}.note cannot be null.`);
    }
  }

  private validateNonEmptyString(value: string, parameterName: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new Error(`${parameterName} must be a non-empty string.`);
    }
  }
}

